/* Letterbox: black bars, demo controls in muted grey outside the watch. */
:root {
  --good: #00e400;
  --moderate: #ffff00;
  --usg: #ff7e00;
  --unhealthy: #ff0000;
  --very_unhealthy: #8f3f97;
  --hazardous: #7e0023;
  --card: #1c1c1e;
  --muted: #8e8e93;
  --font: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Arial, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  min-height: 100%;
  background: #000;
  color: #fff;
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
}

body {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 28px;
  padding: 28px 16px 24px;
  min-height: 100vh;
}

/* ---------- demo frame (outside the watch) ---------- */

.chips {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  max-width: 760px;
}

.chip {
  padding: 7px 14px;
  border: 1px solid #3a3a3c;
  border-radius: 999px;
  color: #aeaeb2;
  font-size: 14px;
  text-decoration: none;
}
.chip:hover { border-color: #636366; color: #fff; }
.chip.active { background: #fff; border-color: #fff; color: #000; font-weight: 600; }

.frame-notes {
  max-width: 520px;
  text-align: center;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.45;
}
.frame-notes p { margin: 0 0 8px; }
.scenario-desc { color: #c7c7cc; }
.decision-ref { font-family: ui-monospace, Menlo, monospace; font-size: 12px; }
.caption { font-size: 12px; color: #636366; }

/* ---------- the watch (Apple Watch 45 mm proportions) ---------- */

.stage { display: flex; justify-content: center; }

.watch {
  position: relative;
  width: 396px;
  height: 484px;
  padding: 16px;
  border-radius: 104px;
  background: linear-gradient(145deg, #3a3a3c 0%, #1c1c1e 45%, #2c2c2e 100%);
  box-shadow: 0 0 0 1px #48484a, 0 30px 80px rgba(255, 255, 255, 0.04);
}
