    "Los Angeles": "America/Los_Angeles",
    "Bengaluru": "Asia/Kolkata",
    "Delhi": "Asia/Kolkata",
    "Mumbai": "Asia/Kolkata",
    "Dubai": "Asia/Dubai",
}

